// ============================================================
// app/products/page.tsx  —— 流式渲染 + Suspense 边界设计
// 技术栈：Next.js 15 App Router / React Server Components
// ============================================================
import { Suspense } from 'react'
import { ProductGrid } from '@/components/product-grid'
import { RecommendPanel } from '@/components/recommend-panel'
import { ProductCardSkeleton, PanelSkeleton } from '@/components/skeletons'

// 强制动态渲染：每次请求都走流式 SSR
export const dynamic = 'force-dynamic'

// ---------- 数据层：提前创建 Promise，避免串行瀑布 ----------
async function getProducts(): Promise<Product[]> {
  const res = await fetch('https://api.example.com/products', {
    // 数据缓存 60 秒：命中缓存时渲染极快，未命中则回源
    next: { revalidate: 60 },
  })
  if (!res.ok) throw new Error('products fetch failed')
  return res.json()
}

async function getRecommendations(): Promise<Item[]> {
  // 个性化推荐接口很慢（~1.5s），且必须 no-store
  const res = await fetch('https://api.example.com/recommend', {
    cache: 'no-store',
  })
  return res.json()
}

export default function ProductsPage() {
  // ✅ 关键：在渲染顶层就把两个请求并发抛出去
  //    它们是 Promise，此刻并没有 await，所以不会互相等待
  const productsPromise = getProducts()
  const recommendPromise = getRecommendations()

  return (
    <main className='mx-auto max-w-6xl p-6'>
      {/* 1️⃣ 静态壳子：随 HTML shell 立刻输出，不包 Suspense */}
      <header className='mb-6'>
        <h1 className='text-2xl font-bold'>商品列表</h1>
        <p className='text-gray-500'>本周热卖 · 每 60 秒更新</p>
      </header>

      {/* 2️⃣ 关键内容：自己的 Suspense 边界，先吐骨架，数据到了再替换 */}
      <section className='mb-10'>
        <Suspense fallback={<ProductCardSkeleton count={9} />}>
          {/* Server Component 内部 await，阻塞只影响这个边界 */}
          <ProductGrid productsPromise={productsPromise} />
        </Suspense>
      </section>

      {/* 3️⃣ 慢接口：完全隔离，绝不拖累商品列表的展示时间 */}
      <aside>
        <h2 className='mb-3 text-lg font-semibold'>为你推荐</h2>
        <Suspense fallback={<PanelSkeleton />}>
          <RecommendPanel recommendPromise={recommendPromise} />
        </Suspense>
      </aside>
    </main>
  )
}

// ============================================================
// components/product-grid.tsx —— 异步 Server Component
// ============================================================
import { use } from 'react' // React 19：在渲染中消费 Promise
import { AddToCartButton } from './add-to-cart-button' // 交互下沉到叶子 client 组件

type Props = { productsPromise: Promise<Product[]> }

export function ProductGrid({ productsPromise }: Props) {
  // use() 会挂起当前 Suspense 边界，Promise 完成后 React 自动续流
  const products = use(productsPromise)

  return (
    <div className='grid grid-cols-3 gap-4'>
      {products.map((p) => (
        <article key={p.id} className='rounded-xl border p-4'>
          <img src={p.image} alt={p.title} className='aspect-square w-full rounded-lg object-cover' />
          <h3 className='mt-2 font-medium'>{p.title}</h3>
          <p className='text-red-600'>¥{p.price}</p>
          {/* 只有这一小块是客户端组件，JS 体积最小化 */}
          <AddToCartButton productId={p.id} />
        </article>
      ))}
    </div>
  )
}

// ============================================================
// components/recommend-panel.tsx
// ============================================================
export function RecommendPanel({ recommendPromise }: { recommendPromise: Promise<Item[]> }) {
  const items = use(recommendPromise)
  return (
    <ul className='grid grid-cols-4 gap-3'>
      {items.map((i) => (
        <li key={i.id} className='rounded-lg bg-gray-50 p-3 text-sm'>{i.name}</li>
      ))}
    </ul>
  )
}

// ============================================================
// components/add-to-cart-button.tsx —— 交互叶子节点（Client）
// ============================================================
'use client'

import { useState, useTransition } from 'react'

export function AddToCartButton({ productId }: { productId: string }) {
  const [count, setCount] = useState(0)
  // useTransition 让加购后的重渲染低优先级进行，不阻塞输入
  const [isPending, startTransition] = useTransition()

  function handleAdd() {
    startTransition(async () => {
      await fetch('/api/cart', {
        method: 'POST',
        body: JSON.stringify({ productId }),
      })
      setCount((c) => c + 1)
    })
  }

  return (
    <button
      onClick={handleAdd}
      disabled={isPending}
      className='mt-2 rounded-lg bg-black px-3 py-1.5 text-white disabled:opacity-50'
    >
      {isPending ? '加入中…' : count > 0 ? `已加购 ${count}` : '加入购物车'}
    </button>
  )
}

